// ============================================================
// Coaching turn understanding — deterministic live intent parse
//
// This is a compact working note for the coach. It answers:
// "What is the user actually asking for in this turn?"
// ============================================================

// @language-guard-exempt: this LLM call returns internal JSON only; user-visible coaching text is generated by the guarded coaching stream.
import { z } from "zod/v4";
import { callLLMStructured } from "@/lib/ai/structured-output";

export type UserRequestType =
  | "asks_why"
  | "asks_how"
  | "asks_what"
  | "asks_opinion"
  | "asks_next_step"
  | "reports_problem"
  | "pushes_back"
  | "shares_feeling"
  | "pastes_jd"
  | "feedback_about_coach"
  | "unknown";

export interface CoachingTurnUnderstanding {
  requestType: UserRequestType;
  needsDirectAnswer: boolean;
  specificAsk: string | null;
  concreteReferences: string[];
  emotionalUndertone: string | null;
  responseObligation: string;
  clarifyIfMissing: string | null;
}

interface ChatMessage {
  role: "user" | "assistant";
  content: string;
}

export const CoachingTurnRequestTypeV2Schema = z.enum([
  "why_question",
  "how_question",
  "opinion_request",
  "emotional_disclosure",
  "report_pushback",
  "career_decision",
  "jd_offer_analysis",
  "coach_feedback",
  "action_review",
  "unclear",
]);

export const CoachingRiskLevelSchema = z.enum([
  "normal",
  "sensitive",
  "crisis",
]);

const ShortListSchema = z.array(z.string().trim().min(1).max(180)).max(8);

export const CoachingTurnUnderstandingV2Schema = z.object({
  requestType: CoachingTurnRequestTypeV2Schema,
  userActualQuestion: z.string().trim().min(1).max(360),
  directAnswerNeeded: z.boolean(),
  concreteObjects: ShortListSchema,
  emotionalSignals: ShortListSchema,
  hiddenAssumptions: ShortListSchema,
  likelyTension: z.string().trim().min(1).max(300).nullable(),
  evidenceNeeded: ShortListSchema,
  nextBestMove: z.string().trim().min(1).max(360),
  riskLevel: CoachingRiskLevelSchema,
});

export type CoachingTurnRequestTypeV2 = z.infer<
  typeof CoachingTurnRequestTypeV2Schema
>;
export type CoachingRiskLevel = z.infer<typeof CoachingRiskLevelSchema>;
export type CoachingTurnUnderstandingV2 = z.infer<
  typeof CoachingTurnUnderstandingV2Schema
>;

const MAX_REFERENCES = 6;

const QUESTION_PATTERNS: Array<{
  type: UserRequestType;
  pattern: RegExp;
}> = [
  {
    type: "asks_why",
    pattern:
      /\bwhy\b|\u4e3a\u4ec0\u4e48|\u600e\u4e48\u56de\u4e8b|\u4ec0\u4e48\u539f\u56e0/i,
  },
  {
    type: "asks_how",
    pattern: /\bhow\b|\u600e\u4e48\u529e|\u600e\u4e48\u505a|\u5982\u4f55/i,
  },
  {
    type: "asks_what",
    pattern:
      /\bwhat\b|\u662f\u4ec0\u4e48|\u4ec0\u4e48\u610f\u601d|\u5230\u5e95/i,
  },
  {
    type: "asks_opinion",
    pattern:
      /\bdo you think\b|\bwhat do you think\b|\u4f60\u89c9\u5f97|\u4f60\u600e\u4e48\u770b/i,
  },
  {
    type: "asks_next_step",
    pattern:
      /\bnext step\b|\bshould i\b|\u4e0b\u4e00\u6b65|\u8be5\u4e0d\u8be5|\u6211\u8be5|\u8981\u4e0d\u8981/i,
  },
];

const CONCRETE_PATTERNS = [
  /AI\s?\u6559\u7ec3/gi,
  /AI\s?\u804a\u5929/gi,
  /AI/gi,
  /\u804c\u4e1a\u62a5\u544a/g,
  /\u62a5\u544a/g,
  /offer/gi,
  /JD/g,
  /\u5c97\u4f4d/g,
  /\u8f6c\u884c/g,
  /\u6362\u5de5\u4f5c/g,
  /\u79bb\u804c/g,
  /\u7b7e\u8bc1/g,
  /\u7ecf\u6d4e/g,
  /\u5bb6\u5ead/g,
  /\u57ce\u5e02/g,
  /\u65b9\u5411/g,
  /\u5efa\u8bae/g,
  /\u56de\u590d/g,
  /\u95ee\u9898/g,
  /\u56f0\u60d1/g,
  /\u7126\u8651/g,
  /\u62bd\u8c61/g,
  /\u865a\u5316/g,
  /\u8868\u9762/g,
  /\u4e0d\u8fde\u8d2f/g,
  /\u4e0d\u7406\u89e3/g,
  /\u7406\u89e3\u6211/g,
  /\u60c5\u7eea/g,
];

function compact(text: string, max = 180): string {
  return text.replace(/\s+/g, " ").trim().slice(0, max);
}

function latestUserText(messages: ChatMessage[]): string {
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i]?.role === "user") return messages[i].content;
  }
  return "";
}

// 16 (was 8): this transcript feeds the V2 understanding LLM that decides how
// the coach should respond. An 8-message window silently dropped everything
// older than ~4 turns from the decision layer, so the coach "forgot" earlier
// context mid-conversation even though the full history reaches the generator.
function recentTranscript(messages: ChatMessage[], maxMessages = 16): string {
  return messages
    .slice(-maxMessages)
    .map((message) => {
      const role = message.role === "assistant" ? "assistant" : "user";
      return `${role}: ${compact(message.content, 900)}`;
    })
    .join("\n");
}

function unique(items: string[]): string[] {
  return [...new Set(items.map((item) => item.trim()).filter(Boolean))];
}

function inferRequestType(text: string): UserRequestType {
  if (
    /job description|\bJD\b|offer|\u5c97\u4f4d|\u804c\u4f4d|\u62db\u8058/i.test(
      text,
    )
  ) {
    return "pastes_jd";
  }
  if (
    /coach|coaching|reply|response|\u6559\u7ec3|\u804a\u5929|\u56de\u590d|\u56de\u7b54/.test(
      text,
    ) &&
    /\u62bd\u8c61|\u865a\u5316|\u8868\u9762|\u4e0d\u8fde\u8d2f|\u4e0d\u7406\u89e3|generic|abstract|shallow|disjointed/i.test(
      text,
    )
  ) {
    return "feedback_about_coach";
  }
  for (const item of QUESTION_PATTERNS) {
    if (item.pattern.test(text)) return item.type;
  }
  if (
    /doesn'?t fit|that'?s not (it|right|quite|what)|not what i (mean|said|want)|you missed|missed (the|my) point|you don'?t (get|understand)|misunderstood|didn'?t (get|understand)|wrong|\boff\b|\u4e0d\u51c6|\u4e0d\u5bf9|\u4e0d\u50cf|\u4e0d\u8ba4\u53ef|\u4e0d\u662f\u8fd9\u6837|\u6ca1\u7406\u89e3|\u8bef\u89e3/i.test(
      text,
    )
  ) {
    return "pushes_back";
  }
  if (
    /\u6211\u89c9\u5f97|\u6211\u611f\u89c9|\u6211\u62c5\u5fc3|\u6211\u5bb3\u6015|i feel|i worry|i'm worried/i.test(
      text,
    )
  ) {
    return "shares_feeling";
  }
  if (
    /\u95ee\u9898|\u56f0\u6270|\u56f0\u60d1|\u5361\u4f4f|\u6ca1\u529e\u6cd5|problem|issue|stuck/i.test(
      text,
    )
  ) {
    return "reports_problem";
  }
  return "unknown";
}

function inferSpecificAsk(text: string, type: UserRequestType): string | null {
  const cleaned = compact(text);
  if (!cleaned) return null;
  if (type === "unknown" || type === "shares_feeling") return null;

  const questionPieces = cleaned
    .split(/(?<=[?？])\s*/)
    .map((piece) => piece.trim())
    .filter(Boolean);
  const question = questionPieces.find((piece) => /[?？]/.test(piece));
  return question ? compact(question, 180) : cleaned;
}

function extractConcreteReferences(text: string): string[] {
  const refs: string[] = [];
  for (const pattern of CONCRETE_PATTERNS) {
    const matches = text.match(pattern);
    if (matches) refs.push(...matches);
  }
  const quoted = text.match(/["“][^"”]{2,40}["”]/g);
  if (quoted)
    refs.push(...quoted.map((item) => item.replace(/^["“]|["”]$/g, "")));
  const latin = text.match(/\b[A-Z][A-Za-z0-9+/#.-]{1,30}\b/g);
  if (latin) refs.push(...latin);
  return unique(refs).slice(0, MAX_REFERENCES);
}

function inferEmotion(text: string): string | null {
  if (
    /\u7126\u8651|\u62c5\u5fc3|\u5bb3\u6015|anxious|worried|scared/i.test(text)
  ) {
    return "anxious";
  }
  if (
    /\u56f0\u60d1|\u8ff7\u832b|\u4e0d\u786e\u5b9a|confused|lost|uncertain/i.test(
      text,
    )
  ) {
    return "confused";
  }
  if (
    /\u4e0d\u6ee1|\u5931\u671b|\u751f\u6c14|\u4e0d\u723d|frustrated|disappointed/i.test(
      text,
    )
  ) {
    return "frustrated";
  }
  if (/\u5361\u4f4f|\u505c\u6ede|stuck|blocked/i.test(text)) {
    return "stuck";
  }
  return null;
}

function inferRiskLevel(text: string): CoachingRiskLevel {
  if (
    /suicide|kill myself|end my life|self.?harm|\u81ea\u6740|\u81ea\u6b8b|\u4e0d\u60f3\u6d3b|\u7ed3\u675f\u4e00\u5207/i.test(
      text,
    )
  ) {
    return "crisis";
  }
  if (
    /therapy|therapist|depress|panic|trauma|\u6291\u90c1|\u5d29\u6e83|\u521b\u4f24|\u6050\u60e7|\u5fc3\u7406\u54a8\u8be2/i.test(
      text,
    )
  ) {
    return "sensitive";
  }
  return "normal";
}

function obligationFor(type: UserRequestType, hasReferences: boolean): string {
  switch (type) {
    case "asks_why":
      return "Answer the why-question first with a concrete causal read, then ask one follow-up only if needed.";
    case "asks_how":
      return "Answer the how-question with a concrete distinction or first step before coaching deeper.";
    case "asks_what":
      return "Define or explain the concrete thing the user asked about before reflecting.";
    case "asks_opinion":
      return "Give a clear, tentative point of view first; do not hide behind another question.";
    case "asks_next_step":
      return "Offer one small next move, grounded in already stated evidence; do not create a broad plan.";
    case "feedback_about_coach":
      return "Treat this as product feedback: diagnose the concrete failure, acknowledge it plainly, and state what will change.";
    case "pastes_jd":
      return "Analyze the concrete role or JD using the user's profile signals; do not ask more setup questions first.";
    case "pushes_back":
      return "Respect the pushback and test what part is wrong; do not defend the report.";
    case "reports_problem":
      return "Name the concrete problem as stated and separate facts from interpretation.";
    case "shares_feeling":
      return "Reflect the feeling through the situation that caused it, not as generic empathy.";
    case "unknown":
      return hasReferences
        ? "Use the concrete reference as the anchor and ask what the user wants to examine about it."
        : "Ask one precise clarifying question before offering interpretation.";
  }
}

function mapV1RequestTypeToV2(
  type: UserRequestType,
  text: string,
): CoachingTurnRequestTypeV2 {
  if (
    /review|check.?in|\u590d\u76d8|\u6ca1\u505a|\u505a\u5b8c|\u884c\u52a8/i.test(
      text,
    )
  ) {
    return "action_review";
  }
  switch (type) {
    case "asks_why":
      return "why_question";
    case "asks_how":
      return "how_question";
    case "asks_opinion":
    case "asks_what":
      return "opinion_request";
    case "asks_next_step":
    case "reports_problem":
      return "career_decision";
    case "pushes_back":
      return "report_pushback";
    case "shares_feeling":
      return "emotional_disclosure";
    case "pastes_jd":
      return "jd_offer_analysis";
    case "feedback_about_coach":
      return "coach_feedback";
    case "unknown":
      return "unclear";
  }
}

function legacyToV2(params: {
  messages: ChatMessage[];
  legacy: CoachingTurnUnderstanding;
}): CoachingTurnUnderstandingV2 {
  const text = latestUserText(params.messages);
  const emotionalSignals = params.legacy.emotionalUndertone
    ? [params.legacy.emotionalUndertone]
    : [];
  const userActualQuestion =
    (params.legacy.specificAsk ?? compact(text, 260)) ||
    "User intent is unclear.";

  return {
    requestType: mapV1RequestTypeToV2(params.legacy.requestType, text),
    userActualQuestion,
    directAnswerNeeded: params.legacy.needsDirectAnswer,
    concreteObjects: params.legacy.concreteReferences,
    emotionalSignals,
    hiddenAssumptions: [],
    likelyTension: null,
    evidenceNeeded: params.legacy.clarifyIfMissing
      ? [params.legacy.clarifyIfMissing]
      : [],
    nextBestMove: params.legacy.responseObligation,
    riskLevel: inferRiskLevel(text),
  };
}

function buildUnderstandingV2Messages(params: {
  messages: ChatMessage[];
  locale: string;
  fallback: CoachingTurnUnderstanding;
}): Array<{ role: "system" | "user"; content: string }> {
  const requestTypes = CoachingTurnRequestTypeV2Schema.options.join(" | ");
  const latest = latestUserText(params.messages);
  const deterministic = {
    requestType: params.fallback.requestType,
    needsDirectAnswer: params.fallback.needsDirectAnswer,
    specificAsk: params.fallback.specificAsk,
    concreteReferences: params.fallback.concreteReferences,
    emotionalUndertone: params.fallback.emotionalUndertone,
    clarifyIfMissing: params.fallback.clarifyIfMissing,
  };

  return [
    {
      role: "system",
      content: `You are the live semantic understanding layer for an AI career coach.
Return JSON only, validated by schema. Do not coach the user.

Classify the user's latest turn into exactly one requestType:
${requestTypes}

Field guidance:
- userActualQuestion: the real question the coach must answer, in the site locale when possible.
- directAnswerNeeded: true for why/how/opinion/report pushback/JD-offer/coach feedback/action review turns where the coach must answer before asking.
- concreteObjects: concrete nouns, quoted phrases, report sections, roles, constraints, JD/offer details, or user phrases.
- emotionalSignals: feelings or stance signals such as anxious, frustrated, resistant, confused, relieved.
- hiddenAssumptions: tentative assumptions implied by the user, never facts.
- likelyTension: one concise tension to test, or null if unclear.
- evidenceNeeded: evidence the coach should seek before making stronger claims.
- nextBestMove: one sentence telling the coach what to do first.
- riskLevel: normal, sensitive, or crisis. Use crisis only for self-harm/suicidal ideation.

Critical coaching rule: if directAnswerNeeded is true, the main coach must answer userActualQuestion first in 1-2 concrete sentences, then ask at most one question.`,
    },
    {
      role: "user",
      content: `Site locale: ${params.locale}
Latest user message:
${compact(latest, 1200)}

Recent transcript:
${recentTranscript(params.messages)}

Deterministic fallback parse:
${JSON.stringify(deterministic)}

Return the JSON object now.`,
    },
  ];
}

export function buildCoachingTurnUnderstanding(
  messages: ChatMessage[],
): CoachingTurnUnderstanding {
  const text = latestUserText(messages);
  const requestType = inferRequestType(text);
  const concreteReferences = extractConcreteReferences(text);
  const specificAsk = inferSpecificAsk(text, requestType);
  const needsDirectAnswer =
    requestType === "asks_why" ||
    requestType === "asks_how" ||
    requestType === "asks_what" ||
    requestType === "asks_opinion" ||
    requestType === "asks_next_step" ||
    requestType === "feedback_about_coach" ||
    requestType === "pushes_back" ||
    requestType === "pastes_jd";
  const clarifyIfMissing =
    concreteReferences.length === 0 && !specificAsk
      ? "No concrete object is clear yet; ask for the missing object instead of abstract coaching."
      : null;

  return {
    requestType,
    needsDirectAnswer,
    specificAsk,
    concreteReferences,
    emotionalUndertone: inferEmotion(text),
    responseObligation: obligationFor(
      requestType,
      concreteReferences.length > 0,
    ),
    clarifyIfMissing,
  };
}

export async function buildCoachingTurnUnderstandingV2(params: {
  messages: ChatMessage[];
  locale: string;
  fallback?: CoachingTurnUnderstanding;
}): Promise<CoachingTurnUnderstandingV2> {
  const fallback =
    params.fallback ?? buildCoachingTurnUnderstanding(params.messages);
  if (!latestUserText(params.messages)) {
    return legacyToV2({ messages: params.messages, legacy: fallback });
  }

  try {
    return await callLLMStructured(
      "coaching-summary",
      buildUnderstandingV2Messages({
        messages: params.messages,
        locale: params.locale,
        fallback,
      }),
      CoachingTurnUnderstandingV2Schema,
      {
        responseFormat: "json",
        temperature: 0.1,
        maxTokens: 700,
        timeoutMs: 15_000,
      },
    );
  } catch {
    return legacyToV2({ messages: params.messages, legacy: fallback });
  }
}

export function coachingTurnUnderstandingV2ToV1(
  understanding: CoachingTurnUnderstandingV2,
  fallback: CoachingTurnUnderstanding,
): CoachingTurnUnderstanding {
  return {
    requestType: fallback.requestType,
    needsDirectAnswer: understanding.directAnswerNeeded,
    specificAsk: understanding.userActualQuestion,
    concreteReferences: understanding.concreteObjects,
    emotionalUndertone:
      understanding.emotionalSignals[0] ?? fallback.emotionalUndertone,
    responseObligation: understanding.nextBestMove,
    clarifyIfMissing:
      understanding.evidenceNeeded[0] ?? fallback.clarifyIfMissing,
  };
}

export function buildCoachingTurnUnderstandingPrompt(
  understanding: CoachingTurnUnderstanding,
  locale: string,
): string {
  const emptyByLocale: Record<string, string> = {
    en: "none",
    zh: "\u65e0",
  };
  const empty = emptyByLocale[locale] ?? emptyByLocale.en;
  const refs =
    understanding.concreteReferences.length > 0
      ? understanding.concreteReferences.join(" | ")
      : empty;

  if (locale === "zh") {
    return `## 本轮用户真实问题解析（内部使用，不要逐字展示）
- requestType: ${understanding.requestType}
- needsDirectAnswer: ${understanding.needsDirectAnswer ? "true" : "false"}
- specificAsk: ${understanding.specificAsk ?? empty}
- concreteReferences: ${refs}
- emotionalUndertone: ${understanding.emotionalUndertone ?? empty}
- responseObligation: ${understanding.responseObligation}
- clarifyIfMissing: ${understanding.clarifyIfMissing ?? empty}

使用方式：先满足 responseObligation。用户问了具体问题时，必须先回答问题，再进入教练式追问；不要用抽象反思替代回答。`;
  }

  return `## User's Live Question Parse (internal, do not display verbatim)
- requestType: ${understanding.requestType}
- needsDirectAnswer: ${understanding.needsDirectAnswer ? "true" : "false"}
- specificAsk: ${understanding.specificAsk ?? empty}
- concreteReferences: ${refs}
- emotionalUndertone: ${understanding.emotionalUndertone ?? empty}
- responseObligation: ${understanding.responseObligation}
- clarifyIfMissing: ${understanding.clarifyIfMissing ?? empty}

How to use this: satisfy responseObligation first. When the user asks a concrete question, answer it before coaching deeper; do not substitute abstract reflection for an answer.`;
}

export function buildCoachingTurnUnderstandingV2Prompt(
  understanding: CoachingTurnUnderstandingV2,
  locale: string,
): string {
  const emptyByLocale: Record<string, string> = {
    en: "none",
    zh: "\u65e0",
  };
  const empty = emptyByLocale[locale] ?? emptyByLocale.en;
  const list = (items: string[]) =>
    items.length > 0 ? items.join(" | ") : empty;

  if (locale === "zh") {
    return `## 本轮用户真实问题解析 V2（LLM 结构化 JSON，内部使用，不要逐字展示）
- requestType: ${understanding.requestType}
- userActualQuestion: ${understanding.userActualQuestion}
- directAnswerNeeded: ${understanding.directAnswerNeeded ? "true" : "false"}
- concreteObjects: ${list(understanding.concreteObjects)}
- emotionalSignals: ${list(understanding.emotionalSignals)}
- hiddenAssumptions: ${list(understanding.hiddenAssumptions)}
- likelyTension: ${understanding.likelyTension ?? empty}
- evidenceNeeded: ${list(understanding.evidenceNeeded)}
- nextBestMove: ${understanding.nextBestMove}
- riskLevel: ${understanding.riskLevel}

使用方式：
- 如果 directAnswerNeeded=true，第一段必须先回答 userActualQuestion，用 1-2 句具体解释承接用户问题。
- 回答之后才进入教练式推进，并且最多一个问题。
- concreteObjects 是本轮必须优先复用的锚点；hiddenAssumptions 和 likelyTension 只能以“我有个试探性理解”方式提出，不能当事实。
- riskLevel=sensitive/crisis 时，优先遵守安全和边界规则。`;
  }

  return `## User's Live Question Parse V2 (LLM structured JSON, internal, do not display verbatim)
- requestType: ${understanding.requestType}
- userActualQuestion: ${understanding.userActualQuestion}
- directAnswerNeeded: ${understanding.directAnswerNeeded ? "true" : "false"}
- concreteObjects: ${list(understanding.concreteObjects)}
- emotionalSignals: ${list(understanding.emotionalSignals)}
- hiddenAssumptions: ${list(understanding.hiddenAssumptions)}
- likelyTension: ${understanding.likelyTension ?? empty}
- evidenceNeeded: ${list(understanding.evidenceNeeded)}
- nextBestMove: ${understanding.nextBestMove}
- riskLevel: ${understanding.riskLevel}

How to use this:
- If directAnswerNeeded=true, the first paragraph must answer userActualQuestion in 1-2 concrete sentences.
- Only after that answer may you coach deeper, and ask at most one question.
- concreteObjects are the turn anchors to reuse first; hiddenAssumptions and likelyTension are tentative hypotheses, not facts.
- If riskLevel=sensitive/crisis, prioritize the safety and boundary rules.`;
}
